{{ config(
            materialized='table',
                post_hook={
                    "sql": "DECLARE is_incremental BOOL DEFAULT TRUE; DECLARE lookback_days INT64 DEFAULT 10; DECLARE reload_from_date DATE; SET reload_from_date = DATE_SUB(CURRENT_DATE(), INTERVAL lookback_days DAY); CREATE TEMP TABLE staged_acefone_calls AS WITH source_data AS ( SELECT CAST(id AS STRING) AS id, CAST(sid AS STRING) AS sid, SAFE_CAST(date AS DATE) AS call_date, SAFE_CAST(time AS TIME) AS call_time, DATETIME( SAFE_CAST(date AS DATE), SAFE_CAST(time AS TIME) ) AS call_datetime, CAST(uuid AS STRING) AS uuid, SAFE.PARSE_JSON(notes) AS notes, CAST(sname AS STRING) AS sname, STRUCT( JSON_VALUE(SAFE.PARSE_JSON(circle), \'$.circle\') AS circle, JSON_VALUE(SAFE.PARSE_JSON(circle), \'$.operator\') AS operator ) AS circle, CAST(reason AS STRING) AS reason, CAST(ref_id AS STRING) AS ref_id, CAST(status AS STRING) AS status, CAST(call_id AS STRING) AS call_id, SAFE_CAST(charges AS FLOAT64) AS charges, CAST(lead_id AS STRING) AS lead_id, CAST(service AS STRING) AS service, CAST(accountid AS STRING) AS accountid, ARRAY( SELECT SAFE.PARSE_JSON(cf) FROM UNNEST(IFNULL(call_flow, [])) AS cf ) AS call_flow, CAST(call_hint AS STRING) AS call_hint, CAST(direction AS STRING) AS direction, SAFE_CAST(end_stamp AS TIMESTAMP) AS end_stamp, SAFE.PARSE_JSON(lead_data) AS lead_data, CAST(agent_name AS STRING) AS agent_name, CAST(did_number AS STRING) AS did_number, CAST(dtmf_input AS STRING) AS dtmf_input, CAST(description AS STRING) AS description, SAFE_CAST(is_whatsapp AS INT64) AS is_whatsapp, CAST(agent_number AS STRING) AS agent_number, CAST(broadcast_id AS STRING) AS broadcast_id, CAST(hangup_cause AS STRING) AS hangup_cause, CAST(u_contact_id AS STRING) AS u_contact_id, SAFE_CAST(call_duration AS FLOAT64) AS call_duration, CAST(caller_id_num AS STRING) AS caller_id_num, CAST(client_number AS STRING) AS client_number, CAST(custom_status AS STRING) AS custom_status, ARRAY( SELECT SAFE.PARSE_JSON(ma) FROM UNNEST(IFNULL(missed_agents, [])) AS ma ) AS missed_agents, CAST(recording_url AS STRING) AS recording_url, CAST(sip_agent_ids AS STRING) AS sip_agent_ids, CAST(u_contact_name AS STRING) AS u_contact_name, CAST(agent_ring_time AS STRING) AS agent_ring_time, CAST(contact_details AS STRING) AS contact_details, CAST(department_name AS STRING) AS department_name, SAFE_CAST(answered_seconds AS FLOAT64) AS answered_seconds, SAFE_CAST(minutes_consumed AS FLOAT64) AS minutes_consumed, SAFE_CAST(support_api_call AS BOOL) AS support_api_call, CAST(agent_hangup_data AS STRING) AS agent_hangup_data, CAST(blocked_number_id AS STRING) AS blocked_number_id, SAFE_CAST(is_sip_trunk_call AS BOOL) AS is_sip_trunk_call, SAFE.PARSE_JSON(dialer_call_details) AS dialer_call_details, SAFE_CAST(total_call_duration AS FLOAT64) AS total_call_duration, SAFE_CAST(voicemail_recording AS BOOL) AS voicemail_recording, CAST(detailed_description AS STRING) AS detailed_description, ARRAY( SELECT SAFE.PARSE_JSON(tma) FROM UNNEST(IFNULL(transfer_missed_agent, [])) AS tma ) AS transfer_missed_agent, CAST(agent_number_with_prefix AS STRING) AS agent_number_with_prefix, SAFE_CAST(is_incoming_from_broadcast AS BOOL) AS is_incoming_from_broadcast, CAST(aws_call_recording_identifier AS STRING) AS aws_call_recording_identifier, CURRENT_TIMESTAMP() AS bq_load_ts FROM `kerala-ayurveda-wh.MapleMonk.Acefone_get_call_detail_records` WHERE NOT is_incremental OR SAFE_CAST(date AS DATE) >= reload_from_date ) SELECT * FROM source_data; IF is_incremental THEN DELETE FROM `kerala-ayurveda-wh.MapleMonk.fact_acefone_call_detail_records` WHERE call_date >= reload_from_date; ELSE TRUNCATE TABLE `kerala-ayurveda-wh.MapleMonk.fact_acefone_call_detail_records`; END IF; INSERT INTO `kerala-ayurveda-wh.MapleMonk.fact_acefone_call_detail_records` SELECT * FROM staged_acefone_calls; DROP TABLE staged_acefone_calls;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
